package com.aditya.day13.notification; import org.springframework.web.bind.annotation.*; import java.time.*; @RestController @RequestMapping("/api/notifications") public class NotificationController{record N(String recipient,String message,Instant sentAt){}@PostMapping public N send(@RequestBody N n){return new N(n.recipient(),n.message(),Instant.now());}@GetMapping("/health")public String health(){return "notification-service-ok";}}